    "dificuldade": "dificil",
    "contexto": "Um oficial de serviço em uma organização militar em Niterói recebe, às 20h, ordem de acionar o socorro para um marinheiro ferido que se encontra em um posto destacado em Arraial do Cabo. Ele deliberadamente não aciona. O marinheiro morre na madrugada, em Arraial do Cabo. Em data posterior, entra em vigor lei que agrava a pena do crime correspondente.",
    "enunciado": "Indique, com fundamento, (a) o lugar do crime e (b) o momento do crime para fins de lei aplicável. Aponte o fato que costuma induzir ao erro.",
    "gabaritoComentado": "**Gabarito:** (a) Crime omissivo: considera-se praticado no lugar em que deveria realizar-se a ação omitida (CPM art. 6º, parte final) — Niterói, onde o oficial deveria acionar o socorro. A ubiquidade (atividade ou resultado) é regra dos comissivos; o lugar da morte (Arraial do Cabo) não define o lugar do crime omissivo. (b) Tempo: momento da ação ou omissão, ainda que outro seja o do resultado (art. 5º) — 20h, quando deveria agir. A lei posterior mais grave não retroage (CF art. 5º, XL). Fato indutor de erro: o local e a hora da morte.\n\n**Resposta plena:** identifica a omissão, aplica a parte final do art. 6º e o art. 5º, afasta a lei mais grave. **Parcial:** acerta o tempo mas aplica ubiquidade ao lugar (ou vice-versa). **Insuficiente:** indica o local da morte com base no resultado.",
