    "contexto": "No convés, o Marinheiro Eco empurra o Marinheiro Foxtrot para machucá-lo. Foxtrot cai e fratura o crânio. O Cabo Golf, responsável pela enfermaria naquele turno, demora uma hora para atender por estar jogando no celular. Foxtrot morre; o laudo diz que a fratura, sem atendimento, levaria à morte, e que o atendimento imediato ‘provavelmente’ o salvaria.",
