    "contexto": "Um capitão de corveta, comandante de uma OM, recebe comunicação de que o seu imediato, capitão de corveta mais antigo que ele, teria desviado verba. O comandante designa, por portaria, um capitão-tenente como encarregado e um cabo como escrivão.",
