    "contexto": "Em IPM sobre agressão, o encarregado intima o Cabo X como testemunha, embora dois depoimentos já o apontem como agressor. A oitiva começa às 17h30, termina às 21h, sem registro de urgência. O cabo não é advertido e admite ter agredido.",
    "enunciado": "Analise a validade da oitiva e o destino da declaração, com fundamento.",
    "gabaritoComentado": "**Gabarito:** Questão: validade da oitiva de quem é materialmente investigado. Norma: slide 24 (o depoente deve ter ciência da qualidade em que é ouvido); ementa do STM no slide 25 (suposto autor deve ser ouvido como indiciado, podendo ter advogado; a falta de advertência sobre silêncio e advogado gera prova ilícita que não deve integrar os autos); CF, art. 5º, LVI e LXIII; CPPM, art. 19 (horário). Aplicação: já havia indícios contra o cabo; foi rotulado testemunha; não houve advertência; a oitiva ultrapassou as 18h sem urgência registrada. Limite: a ilicitude atinge a declaração, não necessariamente os demais elementos independentes do IPM; e quem exclui ou declara ilícita a prova não é o encarregado sozinho arquivando o IPM. Conclusão: declaração ilícita, a ser desentranhada; os demais elementos seguem.\n\n**Plena:** qualidade material + advertência + horário + extensão da ilicitude. **Parcial:** reconhece a ilicitude, mas ignora o horário ou afirma nulidade de todo o IPM. **Insuficiente:** valida a confissão por ter sido espontânea. [NÃO CONFIRMADO NA FONTE PRIMÁRIA] inteiro teor do HC do STM.",
