    "dificuldade": "dificil",
    "contexto": "Um sargento está preso em flagrante por crime militar. O encarregado do IPM (a) determina que ele fique incomunicável ‘por três dias, conforme o CPPM’; (b) nega ao advogado acesso a todos os documentos, inclusive depoimentos já tomados; (c) marca a oitiva do sargento para as 19h, sem urgência; (d) recusa-se a informar ao advogado a data de uma busca que ainda fará.",
    "enunciado": "Na qualidade de assessor jurídico, indique quais atos são irregulares e quais são defensáveis, com fundamento e ressalvas de fonte.",
    "gabaritoComentado": "**Gabarito:** (a) Irregular: a incomunicabilidade (CPPM art. 17 — o slide 27 cita art. 18 [POSSÍVEL ERRO NA FONTE]) é ensinada como não recepcionada; a CF garante ao preso comunicação com família e advogado (art. 5º, LXII–LXIII) e veda a incomunicabilidade até no estado de defesa (art. 136, § 3º, IV). (b) Irregular em parte: o IPM é sigiloso (art. 16), mas o encarregado pode permitir o acesso do advogado, e a leitura ensinada é de que os elementos já documentados não são oponíveis ao defensor [NÃO CONFIRMADO NA FONTE PRIMÁRIA — SV 14]. (c) Irregular: oitiva entre 7h e 18h, salvo urgência inadiável registrada (art. 19); ademais, deve ser ouvido como indiciado e advertido do silêncio e da assistência de advogado (slides 24–25; CF LXIII). (d) Defensável: diligência ainda não realizada pode ser preservada do conhecimento prévio, sob pena de frustração.\n\n**Plena:** quatro atos com fundamento e ressalvas. **Parcial:** trata (b) e (d) da mesma forma. **Insuficiente:** considera o sigilo absoluto ou aplica o art. 17 literalmente.",
